window.ScripturaLexicons.BDAG_PART_0262 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-01\" data-source=\"BDAG\" data-search=\"οὐ μή locução negativa ver μή 4 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐ μή</td><td>locução negativa</td><td>ver μή 4</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-02\" data-source=\"BDAG\" data-search=\"οὖν partícula portanto; então; assim; ora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὖν</td><td>partícula</td><td>portanto; então; assim; ora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-03\" data-source=\"BDAG\" data-search=\"οὔπω advérbio ainda não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὔπω</td><td>advérbio</td><td>ainda não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-04\" data-source=\"BDAG\" data-search=\"οὐρά, ᾶς, ἡ substantivo feminino cauda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐρά, ᾶς, ἡ</td><td>substantivo feminino</td><td>cauda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-05\" data-source=\"BDAG\" data-search=\"οὐράνιος, ον adjetivo celestial; do céu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐράνιος, ον</td><td>adjetivo</td><td>celestial; do céu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-06\" data-source=\"BDAG\" data-search=\"οὐρανόθεν advérbio do céu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐρανόθεν</td><td>advérbio</td><td>do céu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-07\" data-source=\"BDAG\" data-search=\"οὐρανός, οῦ, ὁ substantivo masculino céu; firmamento; morada transcendente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐρανός, οῦ, ὁ</td><td>substantivo masculino</td><td>céu; firmamento; morada transcendente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-08\" data-source=\"BDAG\" data-search=\"Οὐρβανός, οῦ, ὁ nome próprio masculino Urbano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Οὐρβανός, οῦ, ὁ</td><td>nome próprio masculino</td><td>Urbano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-09\" data-source=\"BDAG\" data-search=\"Οὐρίας, ου, ὁ nome próprio masculino Urias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Οὐρίας, ου, ὁ</td><td>nome próprio masculino</td><td>Urias</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-10\" data-source=\"BDAG\" data-search=\"οὖς, ὠτός, τό substantivo neutro ouvido; orelha; compreensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὖς, ὠτός, τό</td><td>substantivo neutro</td><td>ouvido; orelha; compreensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-11\" data-source=\"BDAG\" data-search=\"οὐσία, ας, ἡ substantivo feminino bens; propriedade; riqueza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐσία, ας, ἡ</td><td>substantivo feminino</td><td>bens; propriedade; riqueza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-12\" data-source=\"BDAG\" data-search=\"οὔτε conjunção/advérbio nem; nem sequer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὔτε</td><td>conjunção/advérbio</td><td>nem; nem sequer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-13\" data-source=\"BDAG\" data-search=\"οὗτος, αὕτη, τοῦτο pronome demonstrativo este; esta; isto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὗτος, αὕτη, τοῦτο</td><td>pronome demonstrativo</td><td>este; esta; isto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-14\" data-source=\"BDAG\" data-search=\"οὑτοσί pronome demonstrativo este aqui BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὑτοσί</td><td>pronome demonstrativo</td><td>este aqui</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-15\" data-source=\"BDAG\" data-search=\"οὕτω advérbio assim; desta maneira; tão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὕτω</td><td>advérbio</td><td>assim; desta maneira; tão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-16\" data-source=\"BDAG\" data-search=\"οὐχ forma negativa ver οὐ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐχ</td><td>forma negativa</td><td>ver οὐ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-17\" data-source=\"BDAG\" data-search=\"οὐχί advérbio negativo não; não é?; de modo nenhum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐχί</td><td>advérbio negativo</td><td>não; não é?; de modo nenhum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-18\" data-source=\"BDAG\" data-search=\"ὀφειλέτης, ου, ὁ substantivo masculino devedor; obrigado; pecador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφειλέτης, ου, ὁ</td><td>substantivo masculino</td><td>devedor; obrigado; pecador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-19\" data-source=\"BDAG\" data-search=\"ὀφειλή, ῆς, ἡ substantivo feminino dívida; dever; obrigação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφειλή, ῆς, ἡ</td><td>substantivo feminino</td><td>dívida; dever; obrigação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0262-20\" data-source=\"BDAG\" data-search=\"ὀφείλημα, ατος, τό substantivo neutro dívida; obrigação; pecado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφείλημα, ατος, τό</td><td>substantivo neutro</td><td>dívida; obrigação; pecado</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0262-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐ μή</h1><div class=\"entry-meta\"><span>locução negativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span>, ver <span class=\"greek\">μή</span> 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖν</h1><div class=\"entry-meta\"><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὖν</span> (Hom. e posteriores), partícula que nunca ocorre no início de uma frase. Em nossa literatura é uma conjunção inferencial e, sobretudo, de transição (assim também Hdt. e posteriores [Kühner-G. II p. 326].—B-D-F § 451, 1; Rob. 1191f; Mlt-Turner 337f). ① Inferencial: indica que aquilo que introduz é resultado ou inferência do que precede, assim, portanto, consequentemente, por conseguinte, então. ⓐ Em frases declarativas (PTebt 37, 15 [73 a.C.] <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">γέγραφα</span>, «consequentemente eu … escrevo»; diferentemente em 4 abaixo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:17</a>; 3:10 (ver também 3 abaixo); 7:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>; 11:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:21</a>; 5:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:1</a>; 6:4; 11:5; 13:10; 16:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:16</a>; 7:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:1</a>, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a>; 3J 8 e outros; AcPlCor 2:10, 19.—<span class=\"greek\">ἀπόδοτε</span> <span class=\"greek\">οὖν</span>, bem, então, dai de volta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:21</a> (aqui <span class=\"greek\">οὖν</span> = grego moderno <span class=\"greek\">λοιπόν</span>). ⓑ Em ordens e convites, com força intensiva (PTebt 33, 2 [<span class=\"greek\">φρόν</span>]<span class=\"greek\">τισον</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">γένη</span>(<span class=\"greek\">ται</span>) <span class=\"greek\">ἀκολύθως</span>, «cuidai, portanto, para que as disposições dela [da carta] sejam observadas». Aqui <span class=\"greek\">οὖν</span> retoma a sugestão da importância da carta, devida ao prestígio do destinatário; diferentemente de 3 abaixo): <span class=\"greek\">ποιήσατε</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">ἄξιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μετανοίας</span>, produzi, portanto, fruto digno de arrependimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:8</a> (ver também 3 abaixo); <span class=\"greek\">ἔσεσθε</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">τέλειοι</span>, sede, portanto, perfeitos, 5:48. <span class=\"greek\">μὴ</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">φοβεῖσθε</span>, não temais, portanto, 10:31 (cf. ApcEsdr 7:2; Just., D. 9, 2). <span class=\"greek\">προσερχώμεθα</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span>, aproximemo-nos, pois, com confiança, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:8</a>, 9, 31; 9:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:9</a>; 13:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:18</a>; 10:2, 40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a>; 3:19; 8:22; 23:15, 21 (ver também 4 abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:12</a> (WNauck, Das <span class=\"greek\">οὖν</span>-paräneticum: ZNW 49, ’58, 134f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a> e outros. <span class=\"greek\">νῦν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">πορεύεσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">εἰρήνῃ</span>, agora, pois, ide em paz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:36</a>. ⓒ Em perguntas. <span class=\"greek\">α</span>. Em perguntas reais: <span class=\"greek\">θέλεις</span> <span class=\"greek\">οὖν</span>;, queres, então?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:28</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">εἶ</span>;, és tu, portanto?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.70\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:70</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:39</a>. <span class=\"greek\">νόμον</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">καταργοῦμεν</span>; <span class=\"greek\">μὴ</span> <span class=\"greek\">γένοιτο</span>, anulamos, então, a lei? De modo nenhum, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:31</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:21</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:15</a>. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span>;, por que, então? (Menand., Her. 40, Epitr. 313 S. [137 Kö.]; Dio Chrys. 2, 9; Just., D. 3, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:10</a>; cf. 19:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:25</a>; ou «e então?» (Menand., Epitr. 226 S. [50 Kö], Peric. 744 [321 Kö.]; TestJob 38:7; Just., D. 3, 6; 67, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:10</a>; 20:15, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:30b</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">οὖν</span>; (Menand., Epitr. 221 S. [45 Kö.]; TestJob 38:3; Just., D. 7, 1; Ath. 35, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:42</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπιστεύσατε</span>;, por que, então, não crestes?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:31</a> (TestJob 38:1; Just., D. 47, 2). <span class=\"greek\">πῶς</span> <span class=\"greek\">οὖν</span>; (Menand., Epitr. 441 S. [265 Kö.]; TestJob 19:2; Ar. 9, 9; 10, 7 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:10</a>; Ox 1081, 25= Otero p. 83 (SJCh 90, 2); AcPl Ha 10, 9. <span class=\"greek\">πότε</span> <span class=\"greek\">οὖν</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:7</a>. <span class=\"greek\">πόθεν</span> <span class=\"greek\">οὖν</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:27</a>, 56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:11</a>. <span class=\"greek\">ποῦ</span> <span class=\"greek\">οὖν</span>; (TestJob 32:2ff), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:15</a>. <span class=\"greek\">β</span>. Certas fórmulas são expressões prediletas, especialmente de Paulo: <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span>;, que concluiremos, então? (Dio Chrys. 14 [31], 55; 60; 17 [34], 28; Jos., Bell. 2, 364), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:9</a>; 6:15; 11:7. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐστιν</span>;, que se deve fazer, então?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:15</a>, 26. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">Ἀπολλῶς</span>;, que é Apolo, afinal?, 3:5 (ver 3 abaixo). <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">φημι</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:19</a>. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐροῦμεν</span>;, que diremos, então?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:1</a>; 7:7; 9:14, 30. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐροῦμεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ταῦτα</span>;, 8:31. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a>. <span class=\"greek\">γ</span>. Em perguntas retóricas: <span class=\"greek\">πόσῳ</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">διαφέρει</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">προβάτου</span>, quanto mais, então, vale um ser humano do que uma ovelha?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:12</a>. <span class=\"greek\">πῶς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">σταθήσεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">αὐτοῦ</span>;, como, então, subsistirá o reino (de Belzebu)?, versículo 26.—26:54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14</a> (ver também 4 abaixo). ② Marcador de continuação narrativa, assim, então, ora (ver Rob. 1191: «partícula de transição que relaciona orações ou frases de maneira frouxa, a título de confirmação»). ⓐ <span class=\"greek\">οὖν</span> serve para retomar um assunto depois de uma interrupção: assim, como já se disse: <span class=\"greek\">ἔλεγεν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐκπορευομένοις</span>, dizia, pois, aos que saíam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:7</a> (ligando-se ao versículo 3). Cf. 19:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:6</a>, 9, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:25</a>; 12:5; cf. 25:4 (ver 4 abaixo).—Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:4</a> (retomando o versículo 1); 11:20. ⓑ <span class=\"greek\">οὖν</span> indica transição para algo novo. Assim sobretudo no Evangelho de João (Rob. 1191: «João usa <span class=\"greek\">οὖν</span> isoladamente com liberdade e não precisa de desculpas por fazê-lo; simplesmente conduz a narrativa sem que seja necessário pensar em causa ou resultado»): ora, então, pois, bem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:22</a>; 2:18, 20; 3:25; 4:33, 46, 48; 5:10, 19; 6:60, 67; 7:25, 28, 33, 35, 40; 8:13, 21, 22, 25 (<span class=\"greek\">καὶ</span> <span class=\"greek\">ἔλεγον</span> P 66), 31, 57; 9:7f, 10, 16; 20:30 (ver também 3 abaixo); e frequentemente; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:1</a>; 26:9 (ver também 3 abaixo) e outros. Provavelmente também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:18</a>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπίστευσαν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἰουδαίοι</span>, «ora, os judeus se recusaram a crer» (ver 4 abaixo). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:5</a> (ver também 3 abaixo). ⓒ <span class=\"greek\">οὖν</span> serve para indicar resposta (HDana e JMantey, Manual Grammar of the Gk. NT 1927, p. 254), em passagens em que a tradução «em resposta», «por sua vez» é provável (Ex 8:6): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:9</a>, 48; 6:53 e outros. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:5</a> (ver também 4 abaixo), a ação de Paulo é uma resposta, em termos narrativos, à percepção dos habitantes da ilha: <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἀποτινάξας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θήριον</span>, ele, por sua vez, sacudiu o animal. ⓓ Frequentemente empregado com outras partículas na continuação de discurso ou narrativa: <span class=\"greek\">ἄρα</span> <span class=\"greek\">οὖν</span>, ver <span class=\"greek\">ἄρα</span> 2b. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">οὖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>, 23; 24:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.62\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:62</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:3b</a>; 2 Cl 3:3. <span class=\"greek\">ἐάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">οὖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:8</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">οὖν</span>, ver <span class=\"greek\">εἰ</span> 6k. <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span>, ver <span class=\"greek\">εἰ</span> 6g. <span class=\"greek\">εἴτε</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">εἴτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:31</a>; 15:11. <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">οὖν</span>, ver <span class=\"greek\">ἐπεί</span> 2. <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">δέ</span> (Jos., Ant. 13, 76f; Just., D. 43, 7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:19f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:18f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:4f</a>; 11:19f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25</a>.—Também sem <span class=\"greek\">δέ</span> que marque o contraste (TestJob 40:14; Jos., Ant. 19, 337; Just., A I, 8, 3; Tat. 15, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:6</a>, 18; 2:41; 5:41; 8:25 e outros. <span class=\"greek\">νῦν</span> <span class=\"greek\">οὖν</span> (TestJob 23:7; ApcMos 11:30), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33b</a>; 23:15; também 15:10 (ver <span class=\"greek\">νῦν</span> 2a).—<span class=\"greek\">ὅταν</span> <span class=\"greek\">οὖν</span> (Just., D. 138, 2; Ath. 7, 1; 13, 1; 32, 1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:2</a>; 21:40; 24:15. <span class=\"greek\">ὅτε</span> <span class=\"greek\">οὖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:22</a>; 4:45; 6:24; 13:12, 31; 19:6, 8, 30; 21:15. <span class=\"greek\">τότε</span> <span class=\"greek\">οὖν</span> (ApcEsdr 3:14; Just., D. 56, 19), 11:14; 19:1, 16; 20:8. <span class=\"greek\">ὡς</span> <span class=\"greek\">οὖν</span> (Jos., Ant. 6, 145, Vi. 292; Just., D. 43, 1; 49, 7), 4:1, 40; 11:6; 18:6; 20:11; 21:9; AcPlCor 1:6. <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">οὖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:40</a>.—<span class=\"greek\">οὐκ</span> <span class=\"greek\">οὖν</span>, ver <span class=\"greek\">οὐκοῦν</span>. ③ Propôs-se que alguns vestígios do uso mais antigo de <span class=\"greek\">οὖν</span>, em que a partícula é enfática, = certamente, realmente, sem dúvida etc. (ver L-S-J-M s.v. 1), permaneçam nos papiros (por exemplo PLond I, 28, 4, p. 43 [cerca de 162 a.C.]; PTebt 33, 2 [sobre isso, ver 1b acima]) e no NT (assim M-M., s.v. 3, e Dana e Mantey, op. cit. p. 255f): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:8</a> (ver também 1b acima), 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:30</a> (ver também 2b acima); de fato, certamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:9</a> (ver também 2b acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:5</a> (ver também 1c <span class=\"greek\">β</span> acima) e outros. Por outro lado, como mostram as remissões, há pouca justificativa semântica para criar uma classificação separada (sobre isso, ver especialmente Rob. 1191–92). ④ Também se propôs que <span class=\"greek\">οὖν</span> seja empregado adversativamente (M-M., s.v. 4: «sentido ligeiramente adversativo», com referência a PTebt 37, 15 [73 a.C.]; cf. 1b acima; assim também Dana e Mantey, op. cit. p. 256f) em algumas passagens do NT, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:18</a> (ver 2b acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:21</a>; 25:4; 28:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14</a> (ver 1c <span class=\"greek\">γ</span> acima), com o sentido de mas, porém.—JMantey, Newly Discovered Mngs. for <span class=\"greek\">οὖν</span>: Exp., 8th ser., 22, 1921, 205–14. Mas ver Rob. 1191–92; B-D-F § 451, 1.—Denniston 415–30.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔπω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὔπω</span>, advérbio temporal (Hom. e outros; papiros, LXX; ParJer 5:21; Philo, Joseph.), negação de extensão temporal até um ponto esperado e além dele, ainda não, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:4</a>; 6:17; 7:6, 8a, variante de leitura (por <span class=\"greek\">οὐκ</span>), 8b (variante <span class=\"greek\">οὐδέπω</span> P 66), 30, 39a (Aesop, Fab. 466 P. <span class=\"greek\">οἶνος</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οὔπω</span> <span class=\"greek\">ἦν</span> [as pessoas ainda bebiam néctar]), 39b, variante (por <span class=\"greek\">οὐδέπω</span>); 8:20, 57; 11:30; 20:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:2</a>; 8:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:13</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:8</a>; 12:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:10</a>, 12; IEph 3:1; Hv 3, 9, 5; Hs 9, 5, 2. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὔπω</span>, ninguém jamais (Maximus Tyr. 39, 3i), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2</a> (variante sem <span class=\"greek\">οὔπω</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a> (variante <span class=\"greek\">οὐδέπω</span>). <span class=\"greek\">οὔπω</span> (por <span class=\"greek\">οὐδέπω</span>) … <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">οὐδενί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:16</a>, variante de leitura. Em perguntas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:40</a> (variante <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐκ</span>); 8:17, 21. <span class=\"greek\">οὔπω</span> <span class=\"greek\">γάρ</span>, introduzindo digressão (Jos., Bell. 1, 39; 6, 80), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:24</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐρά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições, papiros, LXX; TestJud 2:6; Jos., Bell. 4, 6, Ant. 3, 228), cauda, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:10</a> (de um escorpião, como no escólio sobre Nicander, Ther. 885; Sib-Or 5, 525), 19ab (cf. Ael. Dion. <span class=\"greek\">α</span>, 109 <span class=\"greek\">ὄφις</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οὐρᾶς</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">ἔχων</span>); 12:4.—B. 209. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐράνιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐράνιος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">οὐρανός</span>; Hom. e posteriores.—Adjetivo de duas terminações, B-D-F § 59, 2; W-S. §11, 1; Mlt-H. 157; escritores áticos formam predominantemente o feminino em -<span class=\"greek\">ία</span>), pertencente ao céu, vindo do céu ou habitando nele, celestial (Diod S 6, 2, 8 <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὐρανίους</span> <span class=\"greek\">θεούς</span>; IAndrosIsis, Hymn to Anubis fr. Chios 1 p. 139; SEG VIII, 2 [117/18 d.C.] <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">οὐρανίου</span>; outros exemplos de <span class=\"greek\">οὐ</span>. como designação de divindades gentílicas: Syria 6, 1925, p. 355, 4; Philo, Omn. Prob. Lib. 130; Jos., C. Ap. 1, 254f <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανίους</span> <span class=\"greek\">θεούς</span>; SibOr 3, 19; 286 <span class=\"greek\">θεὸς</span> <span class=\"greek\">οὐ</span>.—<span class=\"greek\">ἡ</span> <span class=\"greek\">οὐ</span>. <span class=\"greek\">φωνή</span>, Iren. 3, 12, 7 [Harv. II 60, 1]; <span class=\"greek\">παράδειγμα</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">οὐρανίας</span>, Orig., C. Cels. 5, 43, 18; <span class=\"greek\">ἀναστὰς</span> … <span class=\"greek\">οὐράνιον</span> <span class=\"greek\">ἕξεις</span> <span class=\"greek\">πολιτείαν</span>, Did., Gen. 104, 19): <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> (ou <span class=\"greek\">μου</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐράνιος</span>, vosso (ou meu) Pai celestial (Just., A I, 15, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:48</a>; 6:14, 26, 32; 15:13; 18:35 (variante <span class=\"greek\">ἐπουράνιος</span>); 23:9. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.47\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:47</a>, variante. <span class=\"greek\">στρατιὰ</span> <span class=\"greek\">οὐράνιος</span>, hoste ou exército celestial (= <span class=\"hebrew\" dir=\"rtl\">צְבָא</span> <span class=\"hebrew\" dir=\"rtl\">הַשָׁמַיִם</span>, 3 Km 22:19 <span class=\"greek\">ἡ</span> <span class=\"greek\">στρατιὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>; <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐρανία</span> <span class=\"greek\">στρατιά</span>, Orig., C. Cels. 8, 67, 15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:13</a> (variante <span class=\"greek\">οὐρανοῦ</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐράνιος</span> <span class=\"greek\">ὀπτασία</span>, visão celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:19</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐράνιος</span> <span class=\"greek\">βασιλεία</span> = <span class=\"greek\">ἡ</span> <span class=\"greek\">βας</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span>, reino celestial, MPol 22:3.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανόθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐρανόθεν</span>, advérbio de lugar derivado de <span class=\"greek\">οὐρανος</span> (Hom., Hes.; Iambl., Vi. Pyth. 32, 216; PGM 2, 95; 4 Macc 4:10; Philo, Somn. 1, 112; SibOr 8, 341; cf. <span class=\"greek\">μακρόθεν</span>.—Lob., Phryn. p. 93f). No mundo mediterrâneo antigo, a vasta extensão do céu também era entendida como esfera transcendente da ação divina (por exemplo Il. 8, 558). A tradução «do céu» representa, portanto, tanto o aspecto meteorológico quanto o transcendente (Apollon. Rhod. 1, 547 = do céu [como morada do divino]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a> (a chuva vem do céu, mas Deus é a fonte última); 26:13 (uma luz excepcionalmente brilhante surge no céu e está intimamente ligada a uma visão).—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐρανός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>, 24:31 (Hom. e posteriores; «céu» em vários sentidos). ① A parte ou as partes do universo geralmente distinguidas do planeta Terra, céu (assim principalmente no singular; ver B-D-F § 141, 1). ⓐ Mencionado junto com a terra. <span class=\"greek\">α</span>. Formando com ela uma unidade, como totalidade da criação (Pla., Euthyd. 296d <span class=\"greek\">οὐρανὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γῆ</span>; Gen 1:1; 14:19, 22; Tob 7:17 BA; Jdth 9:12; Bel 5; 1 Macc 2:37 e outros; PsSol 8:7; ParJer 5:32; Just., D. 74, 1; PGM 13, 784 <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεύων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐνδιατριβόντων</span>; Orig., C. Cels. 6, 59, 6; Theoph. Ant. 1, 4 [p. 64, 13]): <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span>, o céu e a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a>; 11:25; 24:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:21</a>; 16:17; 21:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:24</a>; 14:15; 17:24 (sobre a ausência do artigo, ver B-D-F § 253, 3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:7</a>; 20:11; Dg 3:4; AcPlCor 2:9; 19. <span class=\"greek\">β</span>. Em posição independente ao lado da terra ou em contraste com ela: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:34f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a> (cf. em ambos Is 66:1). <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῷ</span>) <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπὶ</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">γῆς</span>, no céu e sobre a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:10</a>; 28:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:13</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:3</a>; ISm 11:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῦ</span>, a aparência da terra e do céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:56</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a> (Hg 2:6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>.—<span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span>, os confins da terra, como contraste extremo com o céu, 1 Cl 28:3. Pela palavra criadora de Deus, o céu foi estabelecido e a terra fundada sobre as águas, Hv 1, 3, 4. Nem céu nem terra podem ser compreendidos por medidas humanas, 16:2 (Is 40:12). Sobre <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἄκρου</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">ἄκρου</span> <span class=\"greek\">οὐρανοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:27</a>, ver <span class=\"greek\">ἄκρον</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">οὐρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">γῆ</span>, o primeiro céu e a primeira terra, cederão lugar nos últimos tempos ao <span class=\"greek\">οὐρ</span>. <span class=\"greek\">καινός</span>, novo céu, e à <span class=\"greek\">γῆ</span> <span class=\"greek\">καινή</span>, nova terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:1</a> (cf. Is 65:17; 66:22). ⓑ Como firmamento ou céu sobre a terra, fora do alcance humano, Hm 11:18. Por isso <span class=\"greek\">ἕως</span> <span class=\"greek\">οὐρανοῦ</span> (ApcEsdr 4:32), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:15</a>, ou <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>., Hv 4, 1, 5, como expressões de grande altura. Semelhantemente <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῦ</span>, da terra até o céu, 1 Cl 8:3 (citação das Escrituras de origem desconhecida); GPt 10:40 (sobre um ser transcendente que caminha sobre a terra e cuja cabeça toca o céu, ver Il. 4, 443). Como o céu se estende por toda a terra, <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>., sob o céu = na terra, em toda a terra (Pla., Tim. 23c, Ep. 7, 326c; UPZ 106, 14 [99 a.C.]; Eccl 1:13; 3:1; Just., A II, 5, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:5</a>; 4:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:23</a>; Hs 9, 17, 4; m 12, 4, 2. <span class=\"greek\">ὑποκάτωθεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>, em toda a terra, 1 Cl 53:3 (Dt 9:14). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> (isto é, <span class=\"greek\">χώρας</span>) <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">οὐρανόν</span>, de um lugar da terra a outro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:24</a> (cf. Dt 29:19; Bar 5:3; 2 Macc 2:18 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">τόπον</span>).—Nos últimos dias aparecerão <span class=\"greek\">τέρατα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">ἄνω</span>, prodígios no céu acima, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:19</a> (Jo 3:3, variante de leitura). <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρ</span>., sinal no céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:1</a>, 3 (cf. Diod S 2, 30, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">γινόμενα</span> = o que acontece nos céus; Ael. Aristid. 50, 56 K.=26 p. 519 D., onde a estátua de Asclépio de Pérgamo aparece <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρανῷ</span>). O céu pode até ser enrolado; ver <span class=\"greek\">ἑλίσσω</span>.—A chuva cai do céu (X., An. 4, 2, 2), e o céu é fechado para produzir seca, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:18</a> (cf. 2 Ch 6:26; 7:13; Sir 48:3). Os relâmpagos também vêm do céu (Bacchylides 17, 55f <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span> … <span class=\"greek\">ἀστραπάν</span> [= ático -<span class=\"greek\">ήν</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:18</a>. Do mesmo modo, sobre coisas que descem como chuva para punir pecadores: fogo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:54</a> (cf. 4 Km 1:10; TestAbr A 10 p. 88, 14 [Stone p. 24]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:9</a>; fogo e enxofre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:29</a> (cf. Gen 19:24); granizo apocalíptico, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:21</a>; AcPl Ha 5, 7. ⓒ Como céu estrelado, IEph 19:2: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄστρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>., as estrelas do céu (cf. <span class=\"greek\">ἄστρον</span> e ver Eur., Phoen. 1; Diod S 6, 2, 2 <span class=\"greek\">ἥλιον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σελήνην</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">ἄστρα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">οὐρανόν</span>; Ael. Aristid. 43, 13 K.=1 p. 5 D.; TestAbr A 1 p. 78, 1 [Stone p. 4]; JosAs 2:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀστέρες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>., as estrelas do céu, 1 Cl 32:2 (Gen 22:17); cf. 10:6 (Gen 15:5). No período de tribulação no fim do mundo, as estrelas cairão do céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:29a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:25a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:13</a>; 12:4. Cf. 8:10; 9:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">στρατιὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>. (ver <span class=\"greek\">οὐράνιος</span>), o exército do céu, as estrelas, que alguns israelitas adoraram ilicitamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a> (culto da <span class=\"greek\">στρατιὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>. em hostilidade a YHWH também em Jer 7:18; 19:13; Zeph 1:5; 2 Ch 33:3, 5). Elas também são referidas pelas <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:29b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:26</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:25b</a> (cf. <span class=\"greek\">δύναμις</span> 4). ⓓ Como região da atmosfera (cf. TestAbr A 9 p. 87, 15 [Stone p. 22] <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αἰθέρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>); nela pairam nuvens, as <span class=\"greek\">νεφέλαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>. (ver <span class=\"greek\">νεφέλη</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:30b</a>; 26:64; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.62\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:62</a>; D 16:8. Também aves, <span class=\"greek\">τὰ</span> <span class=\"greek\">πετεινὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> (Gen 1:26; Ps 8:9; Jdth 11:7; ParJer 7:3; cf. Bar 3:17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:26</a>; 8:20; 13:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>; 9:58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:12</a>; 11:6; 6:12 (Gen 1:26), 18; Hs 9, 24, 1; GJs 3:2, códices; 18:2, códices.—<span class=\"greek\">πυρράζει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανός</span>, o céu está avermelhado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:2</a>, 3.—Em relação a <span class=\"greek\">τὸν</span> <span class=\"greek\">σατανᾶν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">πεσόντα</span>, Satanás caído do céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:18</a>, pode-se muito bem conceber a atmosfera como morada dos espíritos malignos. Sobre Satanás como <span class=\"greek\">ἄρχων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐξουσίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀέρος</span>, ver <span class=\"greek\">ἀήρ</span>. Cf. também os <span class=\"greek\">λεγόμενοι</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">εἴτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρ</span>. <span class=\"greek\">εἴτε</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γῆς</span>, assim chamados deuses, quer no céu, quer na terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:5</a>. Em todo caso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:7f</a> fala do dragão e de seus anjos como estando no céu. ⓔ A concepção de mais de um céu (ideia semítica; mas ver FTorm, ZNW 33, ’34, 48–50, que remete a Anaximandro e Aristóteles. Também Ps.-Apollod. 1, 6, 1, 2 ms. e Achilles Tat. 2, 36, 4 e 37, 2 ms. apresentam <span class=\"greek\">οὐρανοί</span>; Himerius, Or. 66 [=Or. 20], 4 <span class=\"greek\">οὐρανοί</span> como morada dos deuses; também Hesychius Miles. [VI d.C.] c. 66 JFlach, a respeito do «pagão ímpio» Triboniano.—Schlatter, Mt 2 p. 58, sobre 3:2: «o plural <span class=\"greek\">οὐρανοί</span> não se encontra nem em Fílon nem em Josefo». Cf. PKatz, Philo’s Bible ’50, 141–46; Mussies 84) também está presente em nossa literatura (ver 1a <span class=\"greek\">α</span>; Theoph. Ant. 1, 4 [p. 64, 15]); entretanto, nem sempre é possível determinar com certeza quando a ideia está efetivamente presente e quando simplesmente sobrevive numa fórmula (no Evangelho de João, o plural está inteiramente ausente; Rv só o tem em 12:12 [da LXX]. Eph sempre emprega o plural. Em outros escritos, singular e plural se alternam sem razão aparente [cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:23</a> com 24 ou Hv 1, 1, 4 com 1, 2, 1; também GPt 10:40f; Ps. 113:11, linhas 1 e 2; TestAbr, TestJob, Just., Tat.]): o terceiro céu (cf. Ps.-Lucian, Philopatris 12 <span class=\"greek\">ἐς</span> <span class=\"greek\">τρίτον</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ἀεροβατήσας</span> [ver <span class=\"greek\">ἀνακαινίζω</span> e <span class=\"greek\">πνεῦμα</span> 8]; PSI 29, 2ff [IV d.C.?] <span class=\"greek\">ἐπικαλοῦμαί</span> <span class=\"greek\">σε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">καθήμενον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρώτῳ</span> <span class=\"greek\">οὐρανῷ</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">β</span>´ <span class=\"greek\">οὐρ</span>. … <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">γ</span>´ <span class=\"greek\">οὐρ</span>.; Simplicius, In Epict. p. 100, 13 Düb. <span class=\"greek\">ὀκτὼ</span> <span class=\"greek\">οὐρανοί</span>; TestLevi 3:3; GrBar 11:1 <span class=\"greek\">εἰς</span> <span class=\"greek\">πέμπτον</span> <span class=\"greek\">οὐ</span>. Combinação do terceiro céu e do paraíso, GrBar 10:1ff; ApcMos 37. Ver <span class=\"greek\">τρίτος</span> 1a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:2</a> (ver JohJeremias, Der Gottesberg 1919, 41ff; Ltzm., Hdb. 4 ’49, exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:3f</a> [bibliografia]). <span class=\"greek\">ὑπεράνω</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span>, acima de todos os céus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:10</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῖς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span>, todas as coisas nos céus e sobre a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:16</a>; cf. versículo 20. <span class=\"greek\">ἔργα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χειρῶν</span> <span class=\"greek\">σού</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">οὐρ</span>., os céus são obra de tuas mãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:10</a> (Ps 101:26).—4:14; 7:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:5</a>, 7, 10, 12f (dos céus, sua destruição na conflagração final e sua substituição pelos <span class=\"greek\">καινοὶ</span> <span class=\"greek\">οὐρ</span>., novos céus); 1 Cl 20:1; 33:3. <span class=\"greek\">τακήσονταί</span> <span class=\"greek\">τινες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span>, alguns dos céus se dissolverão, 2 Cl 16:3.—Ver também Lampe s.v. 2.—Da ideia de diversos níveis celestes, passa-se facilmente a ② Morada transcendente, céu (o plural é preferido nesse sentido: B-D-F § 141, 1; Rob. 408). ⓐ Como habitação (ou trono) de Deus (Sappho, Fgm. 56 D. 2 [=Campbell 54], de Eros; Solon 1, 22 D. 3, de Zeus; Hom. Hymn to Aphrodite 291 [os três com <span class=\"greek\">οὐρ</span>. no singular como morada dos deuses]; Pla., Phdr. 246e <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">Ζεύς</span>; Ps.-Aristot., De Mundo 2, 2; 3, 4, <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρ</span>. como <span class=\"greek\">οἰκητήριον</span> <span class=\"greek\">θεοῦ</span> ou <span class=\"greek\">θεῶν</span>; Dio Chrys. 19[36], 22 <span class=\"greek\">θεῶν</span> <span class=\"greek\">μακάρων</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">οὐρανόν</span>; Artem. 2, 68 p. 159, 13 <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανὸς</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">οἶκος</span>; Ael. Aristid. 43, 14 K.=1 p. 5 D.; Maximus Tyr. 11, 11b; inscrição de Saïtaï, Lídia [<span class=\"greek\">δύναμις</span> 5]; IAndrosIsis, Cyrene 8 p. 129.—Sobre o AT: GWestphal, Jahwes Wohnstätten 1908, 214–73), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.55\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:55f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:1</a>; 16:2b (Is 66:1); Dg 10:7. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">οὐρ</span>., Deus que está nos céus, Hv 1, 1, 6 (cf. Tob 5:17 S). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>., Deus do céu (Gen 24:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:13</a>; 16:11. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανοῖς</span>, o Senhor nos céus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:1</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> (<span class=\"greek\">μου</span>, <span class=\"greek\">ἡμῶν</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> (<span class=\"greek\">τοῖς</span>) <span class=\"greek\">οὐρ</span>., vosso (meu, nosso) Pai que está nos céus (tábua de prata de Amisos: ARW 12, 1909, 25 <span class=\"greek\">ἐγώ</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">καθήμενος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:16</a>, 45; 6:1, 9; 7:11, 21b; 10:33; 12:50; 16:17; 18:10b, 14, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:25f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a>, variante de leitura; D 8:2 (aqui, singular <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρ</span>. Cf. PGM 12, 261 <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">θεῷ</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span>, o Pai que (dá) do céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:13</a> (Jos., Ant. 9, 73 <span class=\"greek\">ἐκχέαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span>). Deus habita nos <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕψη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρ</span>., alturas dos céus, 1 Cl 36:2. Por isso, quem ora olha para o céu: <span class=\"greek\">ἀναβλέπειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>. (ver <span class=\"greek\">ἀναβλέπω</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:41</a>; 7:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:16</a>; MPol 9:2; 14:1. <span class=\"greek\">ἀτενίσας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>. <span class=\"greek\">εἶδεν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">θεοῦ</span>, olhando fixamente para o céu, viu a glória de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.55\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:55</a>; <span class=\"greek\">ἐπάρας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>., erguendo seus olhos ao céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:1</a>.—O Espírito de Deus vem do céu (aberto), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:2</a>(–4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:12</a>; AcPlCor 2:5. A voz de Deus ressoa dali (Maximus Tyr. 35, 7b <span class=\"greek\">Διὸς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">βοῶντος</span>, com as palavras a seguir), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:9</a>; MPol 9:1 (cf. Just., D. 88, 8), e é em geral o lugar de onde se originam pronunciamentos divinos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:5</a>, e seu término, versículo 10. A <span class=\"greek\">ὀργὴ</span> <span class=\"greek\">θεοῦ</span>, ira de Deus, manifesta-se do céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:18</a> (ver Jos., Bell. 1, 630 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">δικαστήν</span>). Também <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐκ</span> (<span class=\"greek\">ἀπὸ</span>) <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρ</span>., sinal proveniente do céu, é sinal dado por Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:16</a>; cf. 21:11.—Lampe s.v. 4. ⓑ Cristo é <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span>, do céu, de natureza celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.47\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:47</a> (ver <span class=\"greek\">ἄνθρωπος</span> 1d. Sobre isso, HKennedy, St. Paul and the Conception of the ‘Heavenly Man’: Exp. 8th ser., 7, 1913, 97–110; EGraham, CQR 113, ’32, 226) e desceu do céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:13b</a>, 31; 6:38, 42, 50 (Ar. 15, 1 <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">καταβάς</span>; Mel., P. 66, 467 <span class=\"greek\">ἀφικόμενος</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανῶν</span>), como <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄρτος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> (ver <span class=\"greek\">ἄρτος</span> 2). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:6</a>. Voltou ao céu (<span class=\"greek\">τὴν</span> <span class=\"greek\">ἔνσαρκον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὐρανοὺ</span> <span class=\"greek\">ἀνάληψιν</span>, Iren. 1, 10, 1 [Harv. I 91, 2]; sobre a ascensão, ver CHönn, Studien zur Geschichte der Hf. im klass. Altertum: Progr. Mannheim 1910; EPfister, Der Reliquienkult im Altertum II 1912, 480ff; HDiels, Himmels u. Höllenfahrten v. Homer bis Dante: NJklA 49, 1922, 239–53; RHolland, Zur Typik der Himmelfahrt: ARW 23, 1925, 207–20; JKroll, Gott u. Hölle ’32, 533 [índice: Ascensus]; WMichaelis, Zur Überl. der Hf.s-geschichte: ThBl 4, 1925, 101–9; AFridrichsen, D. Hf. bei Lk: ibidem 6, 1927, 337–41; GBertram, Die Hf. Jesu vom Kreuz: Deissmann Festschr. 1927, 187–217 [UHolzmeister, ZKT 55, ’31, 44–82]; HSchlier, Christus u. d. Kirche im Eph 1930, 1ff; VLarrañaga, L’Ascension de Notre-Seigneur dans le NT ’38 [do espanhol]. Ver também <span class=\"greek\">ἀνάστασις</span> 2, final, e <span class=\"greek\">διά</span> A 2a) para ali viver em glória: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:10f</a> (AZwiep, The Ascension of the Messiah in Lukan Christology ’97); 2:34; 7:55f; 9:3; 22:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:22</a>; 15:9. Os cristãos aguardam seu retorno do céu: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:10</a>; 4:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:7</a> (Just., A I, 51, 8 e outros).—Quando cessarem as dores messiânicas, <span class=\"greek\">τότε</span> <span class=\"greek\">φανήσεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span>, então aparecerá o sinal do Filho do Homem (que está) no céu; conforme o contexto, o sinal consiste em sua aparição visível em glória celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:30</a>.—Lampe s.v. 10b. ⓒ Como morada dos anjos (Gen 21:17; 22:11; Ps.-Clem., Hom. 8, 12; TestAbr A 4 p. 80, 34 [Stone p. 8]; ParJer 3:2; ApcMos 38; Just., D. 57, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:10a</a>; 22:30; 24:36; 28:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:25</a>; 13:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:15</a>; 22:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:1</a>; 18:1; 19:14; 20:1. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:15</a>.—Lampe s.v. 7. ⓓ Os cristãos que morreram também habitam no céu (cf. Dio Chrys. 23 [40], 35 <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">θείων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μακαρίων</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">τάξιν</span>; Libanius, Or. 21 p. 459, 9 F. <span class=\"greek\">πόρρω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">οἰκοῦντος</span> <span class=\"greek\">χοροῦ</span>; Oenomaus em Eus., PE 5, 33, 5; 12; Artem. 2, 68 p. 160, 25 <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">ἀπαλλαγείσας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σωμάτων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ἀνιέναι</span> <span class=\"greek\">τάχει</span> <span class=\"greek\">χρωμένας</span> <span class=\"greek\">ὑπερβάλλοντι</span>; Himerius, Or. 8 [=23], 23: o espírito da pessoa morta conserva o <span class=\"greek\">σῶμα</span> do morto, <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανός</span>; Quintus Smyrn. 7, 88; TestAbr A 20 p. 103, 26 [Stone p. 54]; TestJob 39:13; ApcEsdr 7:3). A vida deles, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">ζῆν</span>, viver verdadeiramente no céu, contrasta fortemente com o <span class=\"greek\">ὄντως</span> <span class=\"greek\">θάνατος</span>, morte verdadeira, que conduz ao fogo eterno, Dg 10:7b. Roda, que saúda Hermas do céu, Hv 1, 1, 4, não precisa necessariamente ter morrido (ver MDibelius, Hdb. ad loc.), mas ainda assim mostra que o céu está aberto aos devotos. Além disso, a verdadeira cidadania dos cristãos está no céu (Tat. 16, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανοῖς</span> <span class=\"greek\">πορείαν</span>; ver <span class=\"greek\">πολίτευμα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:20</a>; cf. Dg 5:9. Seus nomes estão registrados no céu (ver <span class=\"greek\">βίβλος</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:23</a>. No céu os aguardam o corpo glorificado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1f</a>; a recompensa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>; o tesouro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>; o objeto de sua esperança, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:5</a>; a herança, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:4</a>. É lugar de paz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:38</a>.—<span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>, do céu, descerá à terra a Nova Jerusalém (ver <span class=\"greek\">Ἱεροσόλυμα</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:12</a>; 21:2, 10. ⓔ A concepção de um céu onde residem Deus, os espíritos que o acompanham e os justos mortos facilita a apropriação de certas expressões do AT que personificam o céu: <span class=\"greek\">εὐφραίνεσθε</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">οὐρανοί</span>, alegrai-vos, ó céus (cf. Is 44:23; 49:13; Mel., P. 98, 747), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a>; cf. 18:20; 9:3 (Is 1:2); 11:2 (Jer 2:12); 1 Cl 27:7 (Ps 18:2). ③ Referência indireta a Deus, Deus, extensão figurada de 2 (ver <span class=\"greek\">βασιλεία</span> 1b.—Prática hebraica comum, mas não desconhecida dos politeístas: Philippides Com. [IV/III a.C.] 27 <span class=\"greek\">νὴ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span>. Segundo Clem. Al., Protr. 5, 66, 4 <span class=\"greek\">Θεόφραστος</span> <span class=\"greek\">πῇ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὐρανὸν</span>, <span class=\"greek\">πῇ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὑπονοεῖ</span>, «Teofrasto concebe Deus ora como céu, ora como espírito»; Appian, Hann. 56 §233 <span class=\"greek\">σημεῖα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Διός</span> [linha 14 Viereck-R.]= <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> [linha 16]; JosAs 19:2; SEG XXVIII, 1251, 3 [III/IV d.C.; ver New Docs 3, 49f]). <span class=\"greek\">ἁμαρτάνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρ</span>., pecar contra Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:18</a>, 21. <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀνθρώπων</span>, do céu ou dos homens, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:30f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:4f</a>. <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρ</span>. (GrBar 11:2), no Evangelho de Mateus = <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, reino de Deus, 3:2; 4:17; 5:3, 10, 19f; 7:21; 8:11; 10:7; 11:11f; 13:11, 24, 31, 33, 44f, 47, 52; 16:19; 18:1, 3f, 23; 19:12, 14, 23; 20:1; 22:2; 23:13; 25:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:5</a>, variante de leitura; AcPl Ha 8, 31 (restaurado)=BMM verso 3.—B. 53; 1484. DELG. M-M. DLNT 439–43. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὐρβανός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Οὐρβανός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (tabuinha de chumbo de Hadrumeto 13 [Dssm., B 29; 37—BS 275; 283] <span class=\"greek\">τὸν</span> <span class=\"greek\">Οὐρβανὸν</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἔτεκεν</span> <span class=\"greek\">Οὐρβανά</span>; PSI 27, 7 e outros. O latim Urbanus em inscrições, por exemplo ILS 7566; 7986 e Lghtf., Phil p. 174), Urbano, destinatário de saudação, descrito como <span class=\"greek\">συνεργὸς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span>, nosso cooperador em Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:9</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὐρίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Οὐρίας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\" dir=\"rtl\">אוּרִיָּה</span>), Urias, marido de Bate-Seba, a qual, depois da morte dele, casou-se com Davi e lhe deu Salomão (2 Km 11; 12:24; TestSol; Jos., Ant. 7, 131–41; 144; 146; 153f; Just., D. 141, 4.—O nome também ocorre em outros lugares no AT e em Josefo [genitivo <span class=\"greek\">Οὐρία</span>: Ant. 7, 141; 144]): <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Οὐρίου</span>, a esposa de Urias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:6</a>.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖς, ὠτός, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὖς</span>, <span class=\"greek\">ὠτός</span>, <span class=\"greek\">τό</span> (Hom. e posteriores). ① Órgão auditivo, orelha, ouvido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:33</a>. <span class=\"greek\">δεξιόν</span>, direito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:50</a> (MRostovzeff, ZNW 33, ’34, 196–99, com base em PTebt 793 XI, 1ff [183 a.C.] <span class=\"greek\">Ἡσίοδος</span> … <span class=\"greek\">τὸν</span> <span class=\"greek\">Δωρίωνος</span> <span class=\"greek\">δεξιὸν</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἐξέτεμεν</span>. Também Leo Gramm. 118, 10 IBekker [1842] <span class=\"greek\">ἀπετμήθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεξιὸν</span> <span class=\"greek\">ὦς</span> [= <span class=\"greek\">οὖς</span>]; ver JDoeve, Die Gefangennahme Jesu, Studia Evangelica 73, ’59, 457–80: estabelece conexão com Am 3:12; para outra perspectiva, ver SHall, ibidem 501f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:16</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">οὖς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤκουσεν</span>, o que ouvido algum ouviu, no dito apócrifo de origem desconhecida (ver Hdb. z. NT6 [J] 3 ’33, 4f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:9</a>; 1 Cl 34:8; 2 Cl 11:7; MPol 2:3. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὖς</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τι</span>, dizer algo ao ouvido de alguém, isto é, secretamente ou em confiança, sussurrar (Plut., Demetr. 895 [14, 3]; Jos., Ant. 6, 165; cf. Diog. L. 9, 26 <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὖς</span>; JosAs 24:2 <span class=\"greek\">εἶπον</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὖς</span> <span class=\"greek\">αὐτοῦ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὖς</span> <span class=\"greek\">ἀκούειν</span> (Eur., Or. 616, Andr. 1091), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:27</a>. Diferentemente, <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span>, falar aos ouvidos dos santos, sem sugestão de segredo (cf. 2 Km 3:19), Hv 3, 8, 11; 4, 3, 6. <span class=\"greek\">ὦτα</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δέησιν</span> <span class=\"greek\">αὐτῶν</span>, os ouvidos do Senhor estão atentos à súplica deles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:12</a>; cf. 1 Cl 22:6 (ambos Ps 33:16; cf. GrBar 1:5). <span class=\"greek\">συνέχειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">αὐτῶν</span>, tapar os próprios ouvidos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.57\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:57</a>. <span class=\"greek\">βύειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span>, tapar os ouvidos, IEph 9:1 (ver <span class=\"greek\">βύω</span>). <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτά</span> <span class=\"greek\">τινος</span>, chegar aos ouvidos de alguém (Paroem. Gr.: Zenob. [II d.C.] 3, 49 <span class=\"greek\">εἰς</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ἦλθεν</span>; Ps 17:7; GrBar 1:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:4</a> (cf. Is 5:9); também <span class=\"greek\">γίνεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:44</a>. <span class=\"greek\">ἠκούσθη</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτά</span> <span class=\"greek\">τινος</span>, algo chegou aos ouvidos de alguém (Is 5:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:22</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὠσί</span> <span class=\"greek\">τινος</span>, ao ouvir de alguém (Dt 5:1; 2 Km 3:19; Bar 1:3f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:21</a>. Se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:16</a> for interpretado à luz do versículo 17, pertence aqui; caso seja explicado pelo que precede, pertence a 2. ② Compreensão mental e espiritual, ouvido, capacidade de ouvir, por transferência da percepção sensorial <span class=\"greek\">οὖς</span> (cf. Just., A I, 53, 1 <span class=\"greek\">τοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀκουστικὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νοερὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ἔχουσιν</span>): <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὠσὶ</span> <span class=\"greek\">βαρέως</span> <span class=\"greek\">ἀκούειν</span>, ter ouvidos pesados = compreender lentamente (ou, antes, absolutamente nada), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27a</a> (ambos Is 6:10a); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27b</a> (ambos Is 6:10b). <span class=\"greek\">θέσθε</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τούτους</span>, colocai estas palavras em vossos ouvidos, isto é, guardai-as no coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:44</a> (cf. Ex 17:14 <span class=\"greek\">δὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">Ἰησοῖ</span>); <span class=\"greek\">ὦτα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀκούειν</span>, ouvidos para não ouvir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:8</a> (cf. Dt 29:3). Com <span class=\"greek\">ἔχειν</span> (Hermocles [IV/III a.C.] p. 174, 16 Coll. Alex. [=Athen. 6, 63, 253e], imagens dos deuses <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">ὦτα</span>), <span class=\"greek\">ὦτα</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀκούετε</span>;, tendo ouvidos, não ouvis?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:18</a> (cf. Jer 5:21; Ezk 12:2). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">οὖς</span> <span class=\"greek\">ἀκουσάτω</span>, quem tem ouvido ouça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:7</a>, 11, 17, 29; 3:6, 13, 22; cf. 13:9. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ἀκουέτω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:15</a>; 13:9, 43. <span class=\"greek\">ὸ̔ς</span> (<span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span>) <span class=\"greek\">ἔχει</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">ἀκουέτω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:9</a>, 23; 7:16. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">ἀκουέτω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:8</a>; 14:35; Ox 1081, 35f, dito semelhante 6–8f = Otero p. 83 (SJCh 90, 13f, dito 89, 4–6) (MDibelius, ‘Wer Ohren hat zu hören, der höre’: StKr 83, 1910, 461–71. Cf. Heraclitus [Vorsokrat. 5 22b 34] <span class=\"greek\">ἀξύνετοι</span> <span class=\"greek\">ἀκούσαντες</span> <span class=\"greek\">κωφοῖσιν</span> <span class=\"greek\">ἐοίκασιν</span>). <span class=\"greek\">ἀπερίτμητοι</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὠσίν</span>, incircuncisos no coração e nos ouvidos, isto é, impermeáveis à instrução moral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:51</a> (<span class=\"greek\">ἀπερίτμητος</span> 2).—B. 226. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">εἰμί</span>, «existir»), aquilo que existe e portanto tem substância, bens, propriedade, riqueza (assim Eur., Hdt. e posteriores; inscrições, papiros; Tob 14:13 BA; 3 Macc 3:28; ApcSed 6:7 p. 132, 2 Ja.; Philo; Jos., Bell. 4, 241, Ant., 7, 114; Just., Ath.; Mel., Fgm. 6, 12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:12f</a> (Diog. L. 9, 35: três irmãos, um deles desejando mudar-se para terra distante, dividem a <span class=\"greek\">οὐσία</span> entre si. Segundo ApcSed 6:7 [=p. 132, 2 Ja.], o pai toma posse dos bens de seu filho e o expulsa).—HBerger, Ousia in de dialogen van Plato, ’61.—B. 769. DELG s.v. <span class=\"greek\">εἰμί</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτε</h1><div class=\"entry-meta\"><span>conjunção/advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὔτε</span>, advérbio (Hom. e posteriores. Nos manuscritos frequentemente alterna com <span class=\"greek\">οὐδέ</span>: como variante de leitura, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:26</a>; 20:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:12a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:3</a>; 9:20; 12:8; 20:4; como texto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:12b</a> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἐδιδάχθην</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:3</a>, 4 [ambos <span class=\"greek\">οὔτε</span> <span class=\"greek\">βλέπειν</span> <span class=\"greek\">αὐτό</span>]. Em várias passagens só se atesta <span class=\"greek\">οὐδέ</span> onde seria esperado <span class=\"greek\">οὔτε</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:16</a>; 9:4; 21:23.—Mayser p. 177; B-D-F § 445, 1; Valley s.v. <span class=\"greek\">οὐδέ</span>, final.—SIG 747, 27 [73 a.C.], <span class=\"greek\">οὔτε</span> em lugar de <span class=\"greek\">οὐδέ</span>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:8</a> e 20:4, variantes; ver também 5:4 [<span class=\"greek\">οὐδέ</span> como variante por correto <span class=\"greek\">οὔτε</span>]), e não. <span class=\"greek\">οὔτε</span> … <span class=\"greek\">οὔτε</span>, nem … nem (Jos., Ant. 3, 16; 15, 182): <span class=\"greek\">ὅπου</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">σὴς</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">βρῶσις</span> <span class=\"greek\">ἀφανίζει</span>, onde nem traça nem ferrugem destroem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20</a>. Cf. 22:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:25</a>; 14:68; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:24</a>, variante, 27, variante (em lugar de <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδέ</span>); 14:35; 20:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:21</a>; 5:37; 8:19; 9:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:31</a>; 15:10; 19:37; 28:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:7</a>; 8:8; 11:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:6</a>; 6:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:15f</a>; AcPlCor 2:30. <span class=\"greek\">οὔτε</span> … <span class=\"greek\">οὔτε</span> … <span class=\"greek\">οὔτε</span>, nem … nem … nem (ParJer 5:7 e Just., D. 127, 2, quatro membros; Apc4Esdr Fgm. b, cinco membros; Xenophon Eph. 1, 7, 1 p. 335, 28–30, seis membros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:38f</a> (<span class=\"greek\">οὔτε</span> dez vezes); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9f</a> (<span class=\"greek\">οὔτε</span> sete vezes, continuando e concluindo com <span class=\"greek\">οὐ</span> três vezes); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:5f</a> (<span class=\"greek\">οὔτε</span> três vezes, depois duas vezes numa nova série: <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἄλλων</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a>.—<span class=\"greek\">οὔτε</span> várias vezes depois de <span class=\"greek\">οὐ</span>, versículo 21; antes (e depois) de <span class=\"greek\">οὐ</span>, 21:4. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:12f</a>, <span class=\"greek\">οὔτε</span> tríplice, «nem … nem … nem», continua com <span class=\"greek\">οὐδέ</span>, «e … absolutamente não». <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">γάρ</span> … <span class=\"greek\">οὔτε</span>, pois … não, … nem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:12</a> (variante com <span class=\"greek\">οὐδέ</span> duas vezes). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀφεθήσεται</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνι</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μέλλοντι</span>, não lhe será perdoado, nem neste século nem no vindouro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:32</a> (o segundo <span class=\"greek\">οὔτε</span> talvez seja entendido como intensivo: «nem, asseguro-vos, no século vindouro». Cf. Arrian, Anab. 7, 14, 3 <span class=\"greek\">οὔτε</span> <span class=\"greek\">βασιλεῖ</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">Ἀλεξάνδρῳ</span>, «nem para um rei, nem especialmente para Alexandre»). <span class=\"greek\">οὔτε</span> isolado (TestJob 22:2 <span class=\"greek\">τάχα</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἄρτου</span> <span class=\"greek\">χορτάζεται</span>, «logo [Jó] morrerá de fome por falta de pão»; Just., A I, 43, 2): <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἄξιος</span> <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">ἀνοῖξαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βιβλίον</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">βλέπειν</span> <span class=\"greek\">αὐτό</span>, ninguém foi achado digno de abrir o livro nem de olhá-lo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:4</a>.—<span class=\"greek\">οὔτε</span> … <span class=\"greek\">καί</span> (muito raro no grego antigo [Kühner-G. II 291, 3a: Eur., I. T. 591f]. Mais frequente posteriormente: Plut., Mor. 1115b; Polyaenus 1, 30, 8; Lucian, Jupp. Trag. 5, Dial. Meretr. 2, 4 <span class=\"greek\">οὔτε</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Λεσβία</span>, <span class=\"greek\">Δωρί</span>, <span class=\"greek\">πρὸς</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ἐψεύσατο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">τἀληθῆ</span> <span class=\"greek\">ἀπήγγελκας</span> <span class=\"greek\">Μυρτίῳ</span>; Aelian, NA 1, 57; 11, 9; Longus, Past. 1, 17; 4, 28; ApcSed 14:10; Jos., Bell. 2, 403; 463.—B-D-F § 445, 3; ver Rob. 1189): <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἄντλημα</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φρέαρ</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">βαθύ</span>, não tens balde, e o poço é profundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:11</a>. <span class=\"greek\">οὔτε</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἐπιδέχεται</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀδελφοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">βουλομένους</span> <span class=\"greek\">κωλύει</span>, ele mesmo não recebe os irmãos e impede os que desejam recebê-los, 3J 10.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:12</a>, <span class=\"greek\">οὔτε</span> dificilmente pode estar correto e talvez o texto esteja corrompido (ver B-D-F § 445, 1; sem crítica, Rob. 1189).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὗτος, αὕτη, τοῦτο</h1><div class=\"entry-meta\"><span>pronome demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὗτος</span>, <span class=\"greek\">αὕτη</span>, <span class=\"greek\">τοῦτο</span> (Hom. e posteriores), pronome demonstrativo, empregado como adjetivo e substantivo. Sobre seu uso, ver B-D-F § 290 e outros; W-S. §23; Rob. 697–706; Mlt-Turner 192f; cf. Schwyzer II 208–10. ① Como substantivo, a pessoa ou coisa relativamente próxima no discurso, este, esta, isto (em contraste com <span class=\"greek\">ἐκεῖνος</span>, que se refere a algo relativamente mais distante; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:15</a>; Hm 3:5). ⓐ Em geral. <span class=\"greek\">α</span>. Em referência a algo presente aqui e agora, para chamar a atenção a isso (Appian, Liby. 62 §276 <span class=\"greek\">οὗτος</span> = este homem aqui [referindo-se a alguém presente; ver Schwyzer II 208]. Cf. Pherecrates Com. 134 K. <span class=\"greek\">οὗτος</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἦλθες</span>;, «ei, tu, de onde vieste?»; cf. <span class=\"greek\">ὦ</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">οὗτος</span>, Aristoph., Vesp. 1364; TestAbr B 6 p. 110, 17 [Stone p. 68] <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">εἷς</span>, «ele é um dos três homens»; TestJob 30:2 <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span>, «é ele»): <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">μου</span>, este é meu Filho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:17</a>; 17:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:44ff</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:15</a>, 30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:15</a>; 4:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>, e frequentemente. <span class=\"greek\">τοῦτό</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">μου</span>, isto é meu corpo (ver <span class=\"greek\">εἰμί</span> 2c <span class=\"greek\">α</span>, final), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:19</a> (ÉDelebecque, Études grecques sur l’évangile de Luc ’76, 109–21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:24</a>. <span class=\"greek\">τοῦτό</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμά</span> <span class=\"greek\">μου</span>, isto é meu sangue, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:24</a>.—Com conotação de desprezo (Ael. Aristid. 53 p. 628 D.: <span class=\"greek\">ὦ</span> <span class=\"greek\">οὗτος</span> = «ó miserável!»; do mesmo modo Maximus Tyr. 37, 8d; em refutação Just., D. 39, 4; 128, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:21</a>; 7:39, 49; 15:30 (Reader, Polemo 325); 22:59; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:42</a>, 52. O contexto sugere nuance relacionada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:55f</a> (JosAs 4:13 <span class=\"greek\">οὐχ</span> <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποιμένος</span> …;); 21:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:2f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:15</a>. (Outras referências, Rob. 697; ver também 2a abaixo.)—Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:21</a>. <span class=\"greek\">β</span>. Em referência à pessoa ou coisa mencionada imediatamente antes, este (que acabou de ser mencionado), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:2</a>; 6:71; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:6</a>, 8.—No início de narrativa sobre pessoa já mencionada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:36</a>, 37, variante de leitura, 38, variante; 7:12, variante; 8:42, variante; 16:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:41</a>; 3:2; 12:21; 21:21a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:2</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:12</a> (sobre a alternância entre <span class=\"greek\">αὐτή</span> e <span class=\"greek\">αὕτη</span>, ver B-D-F § 277, 3).—Enfatizando alguém já mencionado, este mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:10</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>); 9:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:17</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">ἐσταυρωμένον</span>, e este, crucificado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:2</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τούτους</span> <span class=\"greek\">ἀποτρέπου</span>, afasta-te de tais pessoas (como acabo de descrevê-las), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:5</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὗτος</span>, também este (acabado de mencionar), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:3</a> (JosAs 7:3 <span class=\"greek\">καὶ</span> <span class=\"greek\">αὕτη</span>). <span class=\"greek\">γ</span>. Referindo-se a assunto mais distante no parágrafo, mas mais próximo do referente principal em discussão (W-S. §23, 2; Rob. 702f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:11</a>; 7:19; 2J 7; Jd 7 (anjos rebeldes, versículo 6). <span class=\"greek\">δ</span>. Referindo-se ao que vem depois: seguido de relativo, <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὅς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:21</a>. <span class=\"greek\">οὗτοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἵτινες</span>, 8:15. <span class=\"greek\">οὗτοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πετρώδη</span> <span class=\"greek\">σπειρόμενοι</span>, <span class=\"greek\">οἳ</span> …, estes são os semeados em solo pedregoso, que …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:16</a>. <span class=\"greek\">ταύτην</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">στῆτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:12</a>. <span class=\"greek\">οὗτοι</span> … <span class=\"greek\">ὅπου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15</a>, ver <span class=\"greek\">ὅπου</span> 1a <span class=\"greek\">α</span>.—Com <span class=\"greek\">ὅτι</span> a seguir: <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κρίσις</span> <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:5</a>; 5:11, 14.—Com <span class=\"greek\">ἵνα</span> a seguir: <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμή</span>, <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:12</a>; cf. 17:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:11</a>, 23; 5:3; 2J 6ab. <span class=\"greek\">τοῦτό</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:29</a>, 39f.—Com infinitivo a seguir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>.—Com particípio a seguir (ApcSed 15:5; Just., D. 2, 1; Mel., P. 68, 486): <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀνοίξας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:37</a>. <span class=\"greek\">οὗτοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">ἀκούσαντες</span>, estes são os que ouviram a palavra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:18</a>. <span class=\"greek\">ἀδελφοί</span> <span class=\"greek\">μου</span> <span class=\"greek\">οὗτοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> … <span class=\"greek\">ἀκούοντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποιοῦντες</span>, estes são meus irmãos, os que … ouvem e fazem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:21</a>.—Com substantivo a seguir: <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">νίκη</span> … <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ἡμῶν</span>, esta é a vitória … nossa fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:4</a>. <span class=\"greek\">ε</span>. Retomando, com ênfase especial, algo mencionado antes — um substantivo: <span class=\"greek\">Μωϋσῆν</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἠρνήσαντο</span> … <span class=\"greek\">τοῦτον</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> …, Moisés, a quem rejeitaram, … foi precisamente aquele a quem Deus …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:35</a> (Ps.-Callisth. 2, 16, 10 <span class=\"greek\">Δαρεῖος</span> …, <span class=\"greek\">οὗτος</span>). <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνδρῶν</span> … <span class=\"greek\">ἕνα</span> <span class=\"greek\">τούτων</span>, dos homens … um destes mesmos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:21f</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, não são os filhos da carne estes os filhos de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:8</a>; cf. versículo 6. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κλήσει</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἐκλήθη</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">μενέτω</span>, cada um permaneça na própria vocação em que foi chamado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:20</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:23</a>; 4:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:7</a>.—Oração relativa: <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ποιήσῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διδάξῃ</span>, <span class=\"greek\">οὗτος</span> …, aquele que fizer e ensinar, este …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:35</a>; 6:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:24b</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:30</a>. <span class=\"greek\">δι</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">σαρκὸς</span> … <span class=\"greek\">διὰ</span> <span class=\"greek\">ταύτης</span>, pela carne pela qual … por esta, AcPl Ha 2, 15. <span class=\"greek\">ὸ̔</span> …, <span class=\"greek\">τοῦτο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:15f</a>, 19f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:7</a>. <span class=\"greek\">ἃ</span> …, <span class=\"greek\">ταῦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:17b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:2</a>. <span class=\"greek\">ὅστις</span> …, <span class=\"greek\">οὗτος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:4</a>. <span class=\"greek\">ἅτινα</span> …, <span class=\"greek\">ταῦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:7</a>. <span class=\"greek\">ὅσοι</span> …, <span class=\"greek\">οὗτοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:12</a>.—Particípio: <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑπομείνας</span>, <span class=\"greek\">οὗτος</span> <span class=\"greek\">σωθήσεται</span>, aquele que perseverar, este será salvo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:22</a>.—13:20, 22; 24:13; 26:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:46</a>; 15:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:4</a>.—Após <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:17</a>; 8:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:23</a>; 3:2.—<span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἀληθῆ</span>, <span class=\"greek\">ὅσα</span> <span class=\"greek\">σεμνά</span>, <span class=\"greek\">ὅσα</span> … (<span class=\"greek\">ὅσα</span> ao todo seis vezes), <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἀρετὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἔπαινος</span>, <span class=\"greek\">ταῦτα</span> <span class=\"greek\">λογίζεσθε</span>, tudo quanto é verdadeiro, tudo quanto é respeitável, tudo quanto …, se há alguma virtude, se há algum louvor, nessas coisas pensai, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:8</a>.—Após <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:31</a>. Após <span class=\"greek\">ὅταν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a>. Após <span class=\"greek\">καθώς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:28</a>.—Após infinitivo articular: <span class=\"greek\">εἰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, <span class=\"greek\">τοῦτο</span> …, se viver na carne, isto …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:22</a>. <span class=\"greek\">ζ</span>. Empregado com <span class=\"greek\">αὐτός</span>: <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">οὗτος</span>, ele próprio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:25</a>. Plural, 24:15, 20. Sobre <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">τοῦτο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:5</a>, ver <span class=\"greek\">αὐτός</span> 1g e Schwyzer II 211. <span class=\"greek\">η</span>. Como sujeito, o demonstrativo pode assumir o gênero de seu predicativo (W-S. §23, 5; Rob. 698): <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">σπέρμα</span>, <span class=\"greek\">οὗτοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span>, a boa semente, estes são os filhos do reino, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:38</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:14f</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:12</a>; 8:11; 22:53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:27</a> (Is 59:21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:24</a>. ⓑ Em particular, o neutro é empregado (sobre o feminino singular, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a> [ambos Ps 117:23], ver B-D-F 138, 2). <span class=\"greek\">α</span>. Referindo-se ao que precede, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.61\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:61</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:17</a>. Como objeto de verbo de dizer (Jos., Vi. 291, Ant. 20, 123 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:6</a>; 7:9; 8:6; 12:33; 18:38 e outros.—Frequentemente com preposição (cf. Johannessohn, Präp. 383 [índice]): <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span>, cf. <span class=\"greek\">διά</span> B 2b. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span>, cf. <span class=\"greek\">εἰς</span> 4f. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τούτου</span>, cf. <span class=\"greek\">ἐκ</span> 3e (= «por essa razão», também PRyl 81, 24). <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>, por essa razão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:2</a>; por isto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:19</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τούτῳ</span>, ver <span class=\"greek\">ἐπί</span> 18b. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦτο</span>, cf. <span class=\"greek\">μετά</span> B 2c. <span class=\"greek\">τούτου</span> <span class=\"greek\">χάριν</span> (PAmh 130, 6 [I d.C.]; Just., D. 1, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:14</a>.—O plural resume o que precede, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:8</a>; 11:27; 24:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:34</a>; 15:11; 21:24 e frequentemente.—Sobre uso midráshico em Ac, ver EEllis, BRigaux Festschr., ’70, 303–12. <span class=\"greek\">β</span>. Com referência ao que vem depois, sobretudo antes de orações que exprimem uma afirmação, finalidade, resultado ou condição, que são assim introduzidas: <span class=\"greek\">τοῦτο</span> <span class=\"greek\">λέγω</span>, seguido de discurso direto, «isto é o que quero dizer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:17</a>; em elipse <span class=\"greek\">τοῦτο</span> <span class=\"greek\">δέ</span>, o ponto é este, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:6</a>; com <span class=\"greek\">ὅτι</span> a seguir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:12</a>. <span class=\"greek\">τοῦτό</span> <span class=\"greek\">φημι</span> <span class=\"greek\">ὅτι</span>, 7:29, variante de leitura; 15:50. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γινώσκειν</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:11</a>; 12:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:20</a>; 3:3 (Just., D. 110, 1). <span class=\"greek\">λογίζῃ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ὅτι</span> …;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:3</a>; <span class=\"greek\">ὁμολογῶ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:14</a>. <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ὅτι</span>, sabendo isto, que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:9</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἔχεις</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:6</a>.—Com <span class=\"greek\">ἵνα</span> a seguir: <span class=\"greek\">πόθεν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἔλθῃ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> …;, como me acontece isto, que a mãe … venha?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:43</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:29</a>, 39.—Com preposição: <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:30</a> (variante <span class=\"greek\">τοῦτο</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:16</a>, 24; 4:9, 10. <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:19</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ὅτι</span>, por esta razão, a saber, que, 5:16, 18; 8:47. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:9</a> e outros. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ἵνα</span>, 13:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:16</a>; Phlm 15. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>, <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:17</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ἐάν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:3</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>, <span class=\"greek\">ὅταν</span>, 5:2.—Antes de infinitivo: <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κέκρικεν</span> …, <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">παρθένον</span>, decidiu isto …, conservar sua virgem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:1</a>. Antes de infinitivo com acusativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>. Introduzindo até mesmo um substantivo seguinte: <span class=\"greek\">τοῦτο</span> <span class=\"greek\">εὐχόμεθα</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κατάρτισιν</span>, isto desejamos, o vosso aperfeiçoamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:9</a>.—Sobre <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">τοῦτο</span>, cf. <span class=\"greek\">αὐτός</span> 1g. <span class=\"greek\">γ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span>, e isto, sobretudo (B-D-F § 290, 5; 442, 9; W-S. §21, 4; Rob. 1181f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:6</a>, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:8</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ταῦτα</span> (também Pla. e outros; ver Kühner-G. I 647), passando de «e isto» para «embora» (Jos., Ant. 2, 266), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a>. <span class=\"greek\">δ</span>. Indicando correspondência: <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">τοῦτο</span> <span class=\"greek\">δέ</span>, ora … ora, não só … mas também (ático), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:33</a> (Tat. 23, 2). <span class=\"greek\">ε</span>. <span class=\"greek\">τοῦτ</span>’ <span class=\"greek\">ἔστιν</span>, <span class=\"greek\">τουτέστι</span>(<span class=\"greek\">ν</span>) (sobre a ortografia, ver B-D-F § 12, 3; 17), isto é ou significa (B-D-F § 132, 2; Rob. 705. Ver também <span class=\"greek\">εἰμί</span> 2c <span class=\"greek\">α</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:19</a>; 19:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:18</a>; 9:8; 10:6, 7, 8; Phlm 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a> e outros. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:12</a> (com <span class=\"greek\">δέ</span>). <span class=\"greek\">ζ</span>. Admite-se uma conotação desfavorável (esse tom é notado por Ps.-Demetr. c. 289 no <span class=\"greek\">Κρατερὸν</span> <span class=\"greek\">τοῦτον</span> [em Demetrius de Fálero]; segundo GBernhardy, Wissenschaftl. Syntax der griech. Sprache 1829, 281, por Heinrici; JWeiss; EFascher, V. Verstehen d. NT 1930, 126 e outros ad loc.; diferentemente W-S. §23, 9; cf. Rob. 704): <span class=\"greek\">καὶ</span> <span class=\"greek\">ταῦτά</span> <span class=\"greek\">τινες</span> <span class=\"greek\">ἦτε</span>, e tais éreis vós, pelo menos alguns de vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:11</a>. ② Como adjetivo, relativo a entidade percebida como presente ou próxima no discurso, este, esta, isto. ⓐ Antes de substantivo (ou expressão substantiva) com artigo (B-D-F § 292; W-S. §23, 10; Rob. 700f): <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἰῶνι</span>, neste século, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:32</a>. Cf. 16:18; 20:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:9</a>; 20:14 e outros. Com nuance de desprezo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:11</a>; cf. 14:30; 15:30 (ver também 1a <span class=\"greek\">α</span>). ⓑ Depois de substantivo com artigo: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λίθων</span> <span class=\"greek\">τούτων</span>, destas pedras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:9</a>. Cf. 5:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:31</a>; 12:56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:13</a>, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:20</a>; 2:6; 11:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:1</a>, 7; 8:6; 11:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:8</a>; 5:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:24</a>. (Frequentemente a posição de <span class=\"greek\">οὗτος</span> varia, ora antes, ora depois do substantivo, nos manuscritos; ver o aparato de Tdf. para as variantes seguintes: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:20</a>; 6:60; 7:36; 9:24; 21:23 e outros.) Às vezes outro adjetivo acompanha o substantivo: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γενεᾶς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκολιᾶς</span> <span class=\"greek\">ταύτης</span>, desta geração perversa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">χήρα</span> <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πτωχή</span>, esta viúva pobre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:3</a>. Cf. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ταῦτα</span>, 2:19, 51, variante de leitura. ⓒ O artigo às vezes está ausente: <span class=\"greek\">μάθημα</span> <span class=\"greek\">τοῦτ</span>’ <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">εὑρημένον</span>, esta lição foi descoberta por eles, Dg 5:3. Nesse caso, não há verdadeira ligação entre demonstrativo e substantivo, mas um deles pertence ao predicado (B-D-F § 292; W-S. §23, 12; Rob. 701f): <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σημείων</span>, fez este início dos sinais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:11</a> (ver 4:54 abaixo). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἀληθὲς</span> <span class=\"greek\">εἴρηκας</span>, disseste isto corretamente, 4:18.—Assim principalmente em combinação com indicação numérica; o substantivo sem artigo deve ser tomado como parte do predicado: <span class=\"greek\">οὗτος</span> <span class=\"greek\">μὴν</span> <span class=\"greek\">ἕκτος</span> <span class=\"greek\">ἐστίν</span>, este é o sexto mês, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:36</a>. <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἀπογραφὴ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐγένετο</span>, este foi o primeiro recenseamento, 2:2. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">δεύτερον</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐποίησεν</span>, fez este, novamente, como segundo sinal, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.54\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:54</a> (ver 2:11 acima). <span class=\"greek\">τρίτην</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἡμέραν</span>, este é o terceiro dia (ver <span class=\"greek\">ἄγω</span> 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:21</a> (Achilles Tat. 7, 11, 2 <span class=\"greek\">τρίτην</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">ἀφανής</span>; Menand., Epitr. 244f S.=68f Kö.; Lucian, Dial. Mort. 13, 3). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">τρίτον</span> <span class=\"greek\">ἐφανερώθη</span>, foi a terceira vez que apareceu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:14</a>. <span class=\"greek\">τρίτον</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἔρχομαι</span>, esta será a terceira vez que venho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a>; cf. 12:14 (cf. Hdt. 5, 76 <span class=\"greek\">τέταρτον</span> <span class=\"greek\">δὴ</span> <span class=\"greek\">τοῦτο</span>; Gen 27:36 <span class=\"greek\">δεύτερον</span> <span class=\"greek\">τοῦτο</span>.—Num 14:22; Judg 16:15).—Mais complexa: <span class=\"greek\">οὐ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλὰς</span> <span class=\"greek\">ταύτας</span> <span class=\"greek\">ἡμέρας</span>, daqui a não muitos dias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:5</a> (Alciphron 1, 14, 2; Achilles Tat. 7, 14, 2 <span class=\"greek\">ὡς</span> <span class=\"greek\">ὀλίγων</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἡμερῶν</span>; POxy 1121, 12 [295 d.C.]; B-D-F § 226; Rob. 702). Mais difícil de todas: <span class=\"greek\">περὶ</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">ταύτης</span> <span class=\"greek\">φωνῆς</span>, acerca desta única declaração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:21</a> (cf. POxy 1152, 5 <span class=\"greek\">βοήθι</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">οἴκῳ</span>. B-D-F § 292; W-S. §20, 10c; Rob. 702 ins).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑτοσί</h1><div class=\"entry-meta\"><span>pronome demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὑτοσί</span> (trágicos, Aristoph. e outros; Joseph.; Just., A II, 14, 1), posição descrita como relativamente próxima, e não distante, no discurso presente, este (aqui): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ταυτησὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, aqui nesta terra, Papias (2:12).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὕτω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὕτω</span> / <span class=\"greek\">οὕτως</span>, advérbio de <span class=\"greek\">οὗτος</span> (Hom. e posteriores; em geral «assim»). A forma <span class=\"greek\">οὕτως</span> é a mais usada, tanto diante de consoantes quanto diante de vogais; a forma <span class=\"greek\">οὕτω</span> (En 98:3, antes de vogal; EpArist, somente antes de consoantes) no NT tem testemunho realmente destacado e é acolhida no texto pela maioria das edições somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:18</a>; outras edições, com o texto recebido, também a adotam em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:15</a>; 7:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:15</a>; 6:19 (B-D-F § 21; W-S. §5, 28b; Mlt-H. 112f; W-H. apêndice 146f. Também nas inscrições [ver Nachmanson 112], papiros [Mayser 242f; Crönert 142] e LXX [Thackeray p. 136] predomina <span class=\"greek\">οὕτως</span>). ① Referindo-se ao que precede, deste modo, assim, dessa maneira. ⓐ Com palavra correlativa: <span class=\"greek\">καθάπερ</span> … <span class=\"greek\">οὕτως</span> (ver <span class=\"greek\">καθάπερ</span>), assim como … assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:4f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a>. <span class=\"greek\">καθὼς</span> … <span class=\"greek\">οὕτως</span>, assim como … assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:30</a>; 17:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:14</a>; 12:50; 14:31; 15:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:5</a>; 10:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:4</a>. <span class=\"greek\">ὡς</span> … <span class=\"greek\">οὕτως</span>, como … assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a> (Is 53:7); 23:11 (<span class=\"greek\">οὕτω</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:15</a>, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:17a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:14</a>. <span class=\"greek\">ὥσπερ</span> … <span class=\"greek\">οὕτως</span> (ParJer 7:26f; GrBar 4:16; ApcEsdr 1:14; Jos., Vi. 1; Just., D. 6, 2; Tat. 5, 2 [<span class=\"greek\">οὕτω</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:40</a>; 13:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:21</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a>, 19, 21; 6:4; GJs 13:1 (final). <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> … <span class=\"greek\">οὕτως</span>, assim como … assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:27f</a>. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τρόπον</span> … <span class=\"greek\">οὕτως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:8</a> (TestJob 27:3ff; Just., A I, 7, 3 e outros). ⓑ Referindo-se ao que precede, de maneira absoluta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>; 6:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:12</a> e outros. <span class=\"greek\">τὸν</span> <span class=\"greek\">οὕτως</span> (a saber, <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>) <span class=\"greek\">ἀναστάντα</span>, aquele que ressuscitou assim (isto é, na carne), AcPlCor 2:25. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">οὕτως</span>, basta disso, 17:2. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">οὕτως</span>, nem mesmo assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:59</a> (Just., D. 12, 2; 46, 6). Expressando a lição moral após figuras de linguagem, parábolas e exemplos (Aristot., Rhet. 1393b [II, 20]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:16</a>; 12:45; 13:49; 18:14; 20:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:21</a>; 15:7, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a>.—<span class=\"greek\">οὕτως</span> pode adquirir sentido específico conforme o que precede: <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἀποκρίνῃ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀρχιερεῖ</span>;, é assim (= com tal insolência) que respondes ao sumo sacerdote?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:22</a>; de maneira tão vil, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:3</a>; com tamanho amor, Dg 10:3; sem se casar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:26</a>, 40. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἀφῶμεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">οὕτως</span>, se o deixarmos (continuar) assim (fazendo milagre após milagre), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:48</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:20</a>. <span class=\"greek\">οὕτως</span> <span class=\"greek\">προοδοιπορούντων</span>, dos que assim seguem adiante, AcPlCor 2:37 (restituído).—<span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a>; 18:35; 24:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:10</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, não é assim entre vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:43</a>. Em elipse (B-D-F § 480, 5) <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">οὕτως</span>, vós não (deveis agir) desse modo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:26</a> (<span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">οὕτως</span> [variante <span class=\"greek\">οὕτως</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιεῖτε</span>], TestNapht 3:4). <span class=\"greek\">οὐχ</span> <span class=\"greek\">οὕτως</span>, <span class=\"greek\">Μαρία</span>, (não conceberás uma criança) dessa maneira, isto é, pela maneira normal das mulheres, GJs 11:3. Resumindo pensamento expresso anteriormente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:11</a>.—Extraindo inferência do que precede, assim, portanto (Horapollo 1, 34 <span class=\"greek\">οὕτω</span> <span class=\"greek\">ὀνομασθήσεται</span>; En 98:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:15</a>; 6:11. <span class=\"greek\">οὕτως</span> <span class=\"greek\">ὅτι</span>, uma vez que assim é, visto que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:16</a>.—Introduzindo uma pergunta: assim: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:40</a> <span class=\"greek\">οὕτως</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἰσχύσατε</span> <span class=\"greek\">μίαν</span> <span class=\"greek\">ὥραν</span> <span class=\"greek\">γρηγορῆσαι</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span>;, então não fostes capazes de vigiar comigo uma única hora?; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:18</a> <span class=\"greek\">οὕτως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ἀσύνετοί</span> <span class=\"greek\">ἐστε</span>;, também vós sois tão obtusos? (isto é, como a multidão); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:5</a> <span class=\"greek\">οὕτως</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔνι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">σοφός</span>, será mesmo que não há entre vós uma só pessoa sábia o bastante para dirimir disputa entre os membros?—Resumindo conteúdo da construção participial precedente (ático: Lysias 2, 79; também Jos., Bell. 2, 129, Ant. 8, 270; B-D-F § 425, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:11</a>; 27:17.—<span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὕτως</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὕτως</span>, um de um modo, outro de outro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:7</a>. ② Relativo ao que segue no discurso, desta maneira, como segue, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:1</a>. De palavras faladas ou escritas: o que assim se introduz vem imediatamente depois, <span class=\"greek\">οὕτως</span> <span class=\"greek\">γέγραπται</span>, assim está escrito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:5</a>. Cf. 6:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:6</a>; 13:34, 47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:4</a>; GJs 21:2 (códices); com <span class=\"greek\">ὅτι</span> recitativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:6</a>; 13:34 (TestAbr A 8 p. 85, 15 [Stone p. 18]). Com infinitivo seguinte (Gen 29:26), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:15</a>. Correlativamente: <span class=\"greek\">οὕτως</span> … <span class=\"greek\">καθώς</span>, assim … como, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:17</a>. <span class=\"greek\">οὕτως</span> … <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τρόπον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>; cf. 27:25. <span class=\"greek\">οὕτως</span> … <span class=\"greek\">ὡς</span>, assim … como (Jos., Ant. 12, 304; Just., A I, 12, 10; 66, 1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:26</a> («é como quando …»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:15</a>; 4:1; 9:26ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:12</a>. <span class=\"greek\">οὕτως</span> … <span class=\"greek\">ὥστε</span> (Hdt. 7, 174; Epict. 1, 11, 4; 4, 11, 19; SIG 1169, 57f <span class=\"greek\">ἔμπυος</span> <span class=\"greek\">ἦς</span> <span class=\"greek\">οὕτω</span> <span class=\"greek\">σφόδρως</span>, <span class=\"greek\">ὥστε</span> … <span class=\"greek\">ἐνέπλησε</span> <span class=\"greek\">πύους</span>, «sofreu a tal ponto de uma ferida supurante que ficou cheio de pus»; Jos., Ant. 8, 206; 9, 255), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:16</a> (ver B-D-F § 391, 2; Mlt. 209; Rob. 1000); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:1</a>. <span class=\"greek\">οὕτως</span> … <span class=\"greek\">ἵνα</span>: <span class=\"greek\">οὕτως</span> <span class=\"greek\">τρέχετε</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">καταλάβητε</span>, correi de modo a alcançar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24</a>.—Funciona como adjetivo (B-D-F §434, 1; HLjungvik, Eranos 62, ’64, 26–31): <span class=\"greek\">ἡ</span> <span class=\"greek\">γένεσις</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἦν</span> (= <span class=\"greek\">τοιαύτη</span> <span class=\"greek\">ἦν</span>), o nascimento aconteceu deste modo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a>.—19:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:18</a> (Gen 15:5). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:17</a>.—Também como substantivo, «algo dessa natureza»: como sujeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:33</a>; como objeto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:12</a>. <span class=\"greek\">οὕτως</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινι</span>, fazer assim a alguém ou por alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:25</a>; 2:48. ③ Marcador de grau relativamente alto, tão, diante de adjetivos e advérbios (Soph., Aristoph. e outros): <span class=\"greek\">σεισμὸς</span> <span class=\"greek\">οὕτω</span> <span class=\"greek\">μέγας</span>, terremoto tão grande, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:18</a>. <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἀνόητοί</span> <span class=\"greek\">ἐστε</span>;, sois tão insensatos?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:3</a> (ver <span class=\"greek\">ἀνόητος</span> a). <span class=\"greek\">οὕτως</span> <span class=\"greek\">φοβερόν</span>, tão terrível, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:21</a>.—<span class=\"greek\">οὕτως</span> <span class=\"greek\">ταχέως</span>, tão depressa (Jos., Vi. 92; cf. <span class=\"greek\">οὕτω</span> <span class=\"greek\">δρομαίως</span>, TestAbr A 7 p. 83, 33 [Stone p. 14]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:6</a>; AcPlCor 2:2.—Diante de verbo, tão intensamente (X., Cyr. 1, 3, 11; TestAbr B 4 p. 108, 11 [Stone p. 64]; Tat. 19, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:11</a>. ④ Excluindo outras considerações, sem mais delongas, simplesmente: <span class=\"greek\">οὕτως</span> (Soph., Phil. 1067 <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἄπει</span>;, «então vais embora sem mais delongas?»; Ael. Aristid. 51, 49 K.=27 p. 546 D.; Aesop, Fab. 308 P.=Babr. 48 Cr.//48 L-P.; Jos., Ant. 14, 438): <span class=\"greek\">Ἰησοῦς</span> … <span class=\"greek\">ἐκαθέζετο</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πηγῇ</span>, Jesus … estava sentado simplesmente junto à fonte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:6</a> (cf. Ammonius, Catena in ev. S. Ioa. p. 216, 21 Cramer <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> ‘<span class=\"greek\">οὕτως</span>’ <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span> ‘<span class=\"greek\">ὡς</span> <span class=\"greek\">ἁπλῶς</span>’ <span class=\"greek\">καὶ</span> ‘<span class=\"greek\">ὡς</span> <span class=\"greek\">ἔτυχε</span>’). Do mesmo modo 8:59, variante de leitura; provavelmente também <span class=\"greek\">ἀναπεσὼν</span> <span class=\"greek\">ἐκεῖνος</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span>, ele, reclinando-se assim junto ao peito de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:25</a> (mas aqui <span class=\"greek\">οὕτως</span> pode também referir-se ao que precede, «assim», isto é, após o sinal de Pedro).—DELG s.v. <span class=\"greek\">οὗτος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐχ</h1><div class=\"entry-meta\"><span>forma negativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐχ</span>, ver <span class=\"greek\">οὐ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐχί</h1><div class=\"entry-meta\"><span>advérbio negativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐχί</span> (forma intensificada de <span class=\"greek\">οὐ</span>; Hom. e posteriores; escritores áticos; SIG 646, 41 [170 a.C.]; 834, 18; PSI 499, 4 [257/256 a.C.]; PEdg 111 [=Sb 6994], 27; LXX; En; TestSol, TestJob, JosAs; ApcEsdr 2:13=p. 26, 6 Tdf.; ApcMos; Jos., Ant. 17, 312 e outros; Just., Tat.), «não» (B-D-F § 432; 427, 2; Rob. 296; 917 e outros). ① Negação simples, não (assim em muitas das passagens acima): <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">καθαροί</span> <span class=\"greek\">ἐστε</span>, nem todos estais limpos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:11</a>; cf. versículo 10 (<span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐχί</span>, como Jos., Ant. 8, 279; Just., A I, 6, 1); 14:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a>. <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:30</a>. <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μᾶλλον</span>, não antes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:2</a> (cf. Just., D. 95, 1f). Seguido de <span class=\"greek\">ἀλλά</span>, não … mas (TestJob 38:6; Just., A I, 23, 1), 10:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:13</a>, variante (por <span class=\"greek\">οὐκ</span>); 12:10. ② Resposta negativa, não, de modo nenhum, com <span class=\"greek\">ἀλλά</span> a seguir (X., Cyr. 1, 3, 4, códices; Gen 18:15; 19:2; 42:12; TestAbr A 5 p. 82, 5 [Stone p. 12] e outros; JosAs 1:14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.60\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:60</a>; 16:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>. <span class=\"greek\">οὐχί</span>, <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span>, <span class=\"greek\">ἀλλά</span>, não, eu vos digo, mas antes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:51</a>; 13:3, 5. (Ver Schwyzer II 597.) ③ Palavra interrogativa em perguntas que esperam resposta afirmativa, não é? (X., Cyr. 8, 3, 46; PGrenf I, 1 I, 25 [II a.C.]; Gen 40:8; Judg 4:6; TestAbr B 10 p. 115, 5 [Stone p, 78]; JosAs 6:5; ApcEsdr 2:13; Just., D. 49, 2): <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">τελῶναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">ποιοῦσιν</span>;, não fazem também os publicanos o mesmo?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:46</a>. Cf. versículo 47; 6:25; 10:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:39</a>; 12:6; 15:8; 17:17 (variante <span class=\"greek\">οὐχ</span>); 24:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:14</a>; 1 Cl 31:2; D 1:3. <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">ἐρεῖ</span> <span class=\"greek\">αὐτῷ</span> …;, não lhe dirá antes …?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:8</a>. <span class=\"greek\">ἢ</span> <span class=\"greek\">οὐχὶ</span> …;, 1 Cl 46:6.—<span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἀδικεῖσθε</span>;, por que não sofreis antes a injustiça?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:7a</a>; cf. versículo 7b. <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐχὶ</span> …; (1 Esdr 4:32; Just., D. 18, 3; 89, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32</a>.—DELG s.v. <span class=\"greek\">οὐ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφειλέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφειλέτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὀφείλω</span>; Soph. e outros; BGU 954, 22; En 6:3 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">ὀφειλέτης</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">μεγάλης</span>; TestJob 11:12). ① Quem deve em sentido monetário, devedor (Pla., Leg. 5, 736d; Plut. e outros), com o montante da dívida no genitivo: <span class=\"greek\">ὀφ</span>. <span class=\"greek\">μυρίων</span> <span class=\"greek\">ταλάντων</span>, quem devia dez mil talentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:24</a> (ver <span class=\"greek\">τάλαντον</span>). ② Quem se encontra sob obrigação em sentido moral ou social, pessoa obrigada, responsável por algo, extensão de 1. ⓐ Devedor: <span class=\"greek\">πάντες</span> <span class=\"greek\">ὀφειλέται</span> <span class=\"greek\">ἐσμὲν</span> <span class=\"greek\">ἁμαρτίας</span>, somos todos devedores em matéria de pecado, Pol 6:1. ⓑ Quem é obrigado a fazer algo: <span class=\"greek\">ὀφειλέτην</span> <span class=\"greek\">εἶναι</span>, estar sob obrigação, com genitivo ou dativo de pessoa ou coisa perante quem se tem obrigação (B-D-F § 190, 1; Rob. 537 e outros): com genitivo de pessoa, estar em dívida para com alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:27</a>. Com dativo de pessoa, 1:14; 8:12. Aquilo que se é obrigado a fazer aparece no genitivo: <span class=\"greek\">ὀφειλέται</span> <span class=\"greek\">ἐσμὲν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ζῆν</span>, estamos obrigados, mas não à carne para viver segundo suas exigências, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:12</a> (ver B-D-F § 400, 2; Rob. 1076). O infinitivo simples (Soph., Aj. 590) ocorre em lugar do infinitivo articular no genitivo: <span class=\"greek\">ὀφ</span>. <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">ποιῆσαι</span>, está obrigado a cumprir toda a lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:3</a>. ⓒ Quem é culpado por uma falta, responsável por transgressão. <span class=\"greek\">α</span>. Em relação às pessoas, com genitivo de quem sofreu a falta: <span class=\"greek\">ἀφήκαμεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">ἡμῶν</span>, perdoamos aos nossos devedores, isto é, aos que pecaram contra nós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:12</a>; cf. D 8:2. <span class=\"greek\">β</span>. Em relação a Deus, pecador (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a> com versículo 2 <span class=\"greek\">ἁμαρτωλοί</span>), em emprego absoluto: <span class=\"greek\">ὅτι</span> <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">ὀφειλέται</span> <span class=\"greek\">ἐγένοντο</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀνθρώπους</span>, que foram pecadores mais do que todas as outras pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a>.—Betz, SM p. 400 n. 479 (bibliografia). DELG s.v. <span class=\"greek\">ὀφείλω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφειλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφειλή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὀφείλω</span>, cf. <span class=\"greek\">ὀφείλημα</span>), segundo Etym. Mag., com referência a X., De Vect. (Ways and Means), raramente empregado. ① Aquilo que alguém deve em sentido financeiro, obrigação, dívida (assim frequentemente em papiros e óstracos [desde III a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:32</a>. No plural, tributos e impostos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:7</a>. Essa passagem demonstra a fácil transferência para ② aquilo que se deve fazer, dever. ⓐ Aquilo que é apropriado numa relação social: obrigação de satisfazer conjugalmente o cônjuge, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:3</a>. No plural, respeito e honra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:7</a> (ver também 1 acima). ⓑ Falha no cumprimento de obrigações morais: <span class=\"greek\">ἄφες</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">ἡμῶν</span>, perdoa-nos nossa dívida, D 8:2.—DELG s.v. <span class=\"greek\">ὀφείλω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0262-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφείλημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφείλημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὀφείλω</span>, cf. <span class=\"greek\">ὀφειλή</span>; Thu. e outros; inscrições, papiros, LXX). ① Aquilo que se deve em sentido financeiro, dívida, obrigação, o que é devido (Pla., Leg. 4, 717b; Aristot., EN 8, 15, 1162b, 28; 9, 2, 1165a, 3; SIG 1108, 10 [III/II a.C.]; PHib 42, 10 [262 a.C.]; PLond III, 1203, 4 p. 10 [113 a.C.]; POxy 494, 10 <span class=\"greek\">ὀφειλήματα</span>; Dt 24:10; I Esdr 3:20; 1 Macc 15:8), sobre pagamento pelo trabalho realizado: <span class=\"greek\">οὐ</span> <span class=\"greek\">λογίζεται</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ὀφείλημα</span>, considera-se não como favor, mas como o que é devido a alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:4</a> (sobre o contraste <span class=\"greek\">χάρις</span> – <span class=\"greek\">ὀφείλημα</span>, cf. Thu. 2, 40, 4 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">χάριν</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἐς</span> <span class=\"greek\">ὀφείλημα</span> = «não como favor, mas como pagamento de uma obrigação». A referência aqui é à reciprocidade em geral). ② Obrigação em sentido moral, dívida = pecado (como o aramaico <span class=\"hebrew\" dir=\"rtl\">חוֹבָא</span> na literatura rabínica; ver MBlack, Aramaic Approach 3, ’67, 140): <span class=\"greek\">ἄφες</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">ἡμῶν</span>, perdoa nossas dívidas (= pecados), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:12</a> (a passagem paralela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:4</a> tem <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ἡμῶν</span>). Betz, SM 400–404.—DELG s.v. <span class=\"greek\">ὀφείλω</span>. M-M. TW.</p></section></article>"};
